-- Synthetic catalog-only prerequisite for byte-unchanged historical migration513.
-- No Auth users, session identities, owner inventory or production connection.
begin;
do $guard$ begin
 if current_setting('max_worker_processes')<>'0'
 or (select count(*) from supabase_migrations.schema_migrations)<>512
 or (select count(*) from public.card_prints)<>1294
 or exists(select 1 from auth.users)
 or exists(select 1 from public.vault_item_instances)
 or exists(select 1 from public.sets where code in('bog','bp'))
 then raise exception 'SEARCH_LOCAL_BOG_PREREQUISITE';end if;
end $guard$;
commit;
